PixelImageMatrixImage FormatsThresholding Modes <p><pre><code>typedef struct Pixel {
    uint8_t r, g, b, i;
} Pixel;
</code></pre> Represents a single pixel with unsigned 8-bit depth and 4 channels. Channel <code>i</code> stores intensity (greyscale), while channels <code>r</code>, <code>g</code>, <code>b</code> store color.</p> <p><pre><code>typedef struct {
    int height, width;
    Pixel **map;
} Image;
</code></pre> Internal representation of an image, stored in a 2D container a using row-pointer map. Each pixel contains both RGB and intensity representations.</p> <p><pre><code>typedef struct {
    int height, width;
    double **map;
} Matrix;
</code></pre> Floating-point matrix used for high-precision operations (e.g., convolution).</p> <p><pre><code>typedef enum cvl_format {
    CVL_FMT_UNKNOWN,
    CVL_FMT_PBM,
    CVL_FMT_PGM,
    CVL_FMT_PPM,
} cvl_format;
</code></pre> Supported image formats.</p> <pre><code>typedef enum cvl_thresh_type {
    CVL_THRESH_BINARY,
    CVL_THRESH_BINARY_INV,
    CVL_THRESH_TRUNC,
    CVL_THRESH_TOZERO,
    CVL_THRESH_TOZERO_INV,
} cvl_thresh_type;
</code></pre> <p>Supported Thresholding Modes.</p> mode operation CVL_THRESH_BINARY \(\text{dst}(x, y) = \begin{cases} \text{maxval} &amp; \text{src}(x, y) &gt; \text{thresh} \\ 0 &amp; \text{otherwise} \end{cases}\) CVL_THRESH_BINARY_INV \(\text{dst}(x, y) = \begin{cases} 0 &amp; \text{src}(x, y) &gt; \text{thresh} \\ \text{maxval} &amp; \text{otherwise} \end{cases}\) CVL_THRESH_TRUNC \(\text{dst}(x, y) = \begin{cases} \text{thresh} &amp; \text{src}(x, y) &gt; \text{thresh} \\ \text{src}(x, y) &amp; \text{otherwise} \end{cases}\) CVL_THRESH_TOZERO \(\text{dst}(x, y) = \begin{cases} \text{src}(x, y) &amp; \text{src}(x, y) &gt; \text{thresh} \\ 0 &amp; \text{otherwise} \end{cases}\) CVL_THRESH_TOZERO_INV \(\text{dst}(x, y) = \begin{cases} 0 &amp; \text{src}(x, y) &gt; \text{thresh} \\ \text{src}(x, y) &amp; \text{otherwise} \end{cases}\)

TokenTokenStreamCommandPipeline <pre><code>typedef struct Token {
    TokenType type;
    char *text; // lexeme
} Token;
</code></pre> Example <pre><code>Token pipe          = { T_PIPE: "|" };
Token redir_in      = { T_REDIR_IN: "&lt;" };
Token redir_out     = { T_REDIR_OUT: "&gt;" };
Token redir_append  = { T_REDIR_APPEND: "&gt;&gt;" };
Token word          = { T_WORD: "everything_else" };
</code></pre> <pre><code>typedef struct TokenStream {
    Token *tokens;
    int size;
} TokenStream;
</code></pre> Example <pre><code>input = "grep foo &lt; in.txt | sort &gt; out.txt | uniq &gt;&gt; append.txt";

tokens = {
    { T_WORD: "grep" },
    { T_WORD: "foo" },
    { T_REDIR_IN: "&lt;" },
    { T_WORD: "in.txt" },

    { T_PIPE: "|" },

    { T_WORD: "sort" },
    { T_REDIR_OUT: "&gt;" },
    { T_WORD: "out.txt" },

    { T_PIPE: "|" },

    { T_WORD: "uniq" },
    { T_REDIR_APPEND: "&gt;&gt;" },
    { T_WORD: "append.txt" }
};
</code></pre> <p>Warning</p> <p>I am refactoring for a new Command struct.</p> <pre><code>typedef struct Command {
    char **argv;
    char *infile;
    char *outfile;
    bool append;
    bool is_first;
    bool is_last;
} Command;
</code></pre> Example <pre><code>input = "grep foo &lt; in.txt | sort &gt; out.txt | uniq &gt;&gt; append.txt";

cmd_1 = {
    argv: [ "grep", "foo", NULL ],
    infile: "in.txt",
    outfile: NULL,
    append: false,
    is_first: true,
    is_last: false
};

cmd_2 = {
    argv: [ "sort", NULL ],
    infile: NULL,
    outfile: "out.txt",
    append: false,
    is_first: false,
    is_last: false
};

cmd_3 = {
    argv: [ "uniq", NULL ],
    infile: NULL,
    outfile: "append.txt",
    append: true,
    is_first: false,
    is_last: true
};
</code></pre> <pre><code>typedef struct Pipeline {
    Command *cmds;
    int size;
} Pipeline;
</code></pre> Example <pre><code>input = "grep foo &lt; in.txt | sort &gt; out.txt | uniq &gt;&gt; append.txt";

pipeline = {
    cmds: [ cmd_1, cmd_2, cmd_3 ],
    size: 3
};
</code></pre>

